import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.TreeMap;

public final class HashRing {
    private final int replicas;
    private final TreeMap<Long, String> ring = new TreeMap<>();

    public HashRing(List<String> nodes, int replicas) {
        this.replicas = replicas;
        for (String node : nodes) {
            addNode(node);
        }
    }

    private static long hashPoint(String s) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] digest = md.digest(s.getBytes(StandardCharsets.UTF_8));
            long value = 0;
            for (int i = 0; i < 8; i++) {
                value = (value << 8) | (digest[i] & 0xFF);
            }
            return value & Long.MAX_VALUE;
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException(e);
        }
    }

    public void addNode(String node) {
        for (int i = 0; i < replicas; i++) {
            ring.put(hashPoint(node + ":" + i), node);
        }
    }

    public void removeNode(String node) {
        for (int i = 0; i < replicas; i++) {
            ring.remove(hashPoint(node + ":" + i));
        }
    }

    public String getNode(String key) {
        long point = hashPoint(key);
        var tail = ring.tailMap(point);
        Long targetKey = tail.isEmpty() ? ring.firstKey() : tail.firstKey();
        return ring.get(targetKey);
    }
}

