import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public final class HashRingTest {
    public static void main(String[] args) {
        checkEveryKeyMapsToACurrentNode();
        checkDeterministic();
        checkRemovingANodeOnlyMovesThatNodesOwnKeys();
        System.out.println("all tests passed");
    }

    static void checkEveryKeyMapsToACurrentNode() {
        HashRing ring = new HashRing(List.of("a", "b", "c"), 50);
        for (int i = 0; i < 200; i++) {
            String node = ring.getNode("key-" + i);
            if (!node.equals("a") && !node.equals("b") && !node.equals("c")) {
                throw new AssertionError("unexpected node " + node);
            }
        }
    }

    static void checkDeterministic() {
        HashRing ring = new HashRing(List.of("a", "b", "c"), 50);
        if (!ring.getNode("stable-key").equals(ring.getNode("stable-key"))) {
            throw new AssertionError("expected deterministic mapping");
        }
    }

    static void checkRemovingANodeOnlyMovesThatNodesOwnKeys() {
        List<String> nodes = List.of("n0", "n1", "n2", "n3", "n4");
        HashRing ring = new HashRing(nodes, 100);
        List<String> keys = new ArrayList<>();
        for (int i = 0; i < 1000; i++) keys.add("key-" + i);
        Map<String, String> before = new HashMap<>();
        for (String k : keys) before.put(k, ring.getNode(k));

        ring.removeNode("n2");

        int moved = 0;
        for (String k : keys) {
            String after = ring.getNode(k);
            if (!after.equals(before.get(k))) {
                moved++;
                if (!before.get(k).equals("n2")) {
                    throw new AssertionError("key " + k + " moved but was not on removed node n2");
                }
            }
            if (after.equals("n2")) {
                throw new AssertionError("key " + k + " still maps to removed node n2");
            }
        }
        if (moved == 0) {
            throw new AssertionError("expected removing a node to move at least some keys");
        }
    }
}

